//! The six DNAChisel specifications the REJ design uses.
//!
//! Ported from `dnachisel.builtin_specifications`. Scores, locations, labels
//! and messages all match the Python originals, because `tests/parity.rs`
//! compares them against fixtures generated by the real DNAChisel — including
//! a couple of quirks noted inline that would be tempting to "fix".
//!
//! Two attributes drive the solver:
//!
//!   * `enforced_by_nucleotide_restrictions` — the spec is satisfied by
//!     construction (it only narrows the mutation space), so the solver never
//!     evaluates it. True for EnforceTranslation and AvoidChanges.
//!   * `best_possible_score` — lets the solver stop early once an objective
//!     cannot improve further. Every spec here tops out at 0.

use std::collections::{HashMap, HashSet};
use std::sync::OnceLock;

use crate::biotools::{
    backtranslation, differing_indices, gc_content, group_nearby_indices, reverse_complement,
    translate,
};
use crate::location::Location;
use crate::pattern::Pattern;
use crate::tables::{HUMAN_CODON_LOG_FREQ, HUMAN_LOG_BEST, MOUSE_CODON_LOG_FREQ, MOUSE_LOG_BEST};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Species {
    Human,
    Mouse,
}

impl Species {
    pub fn table_name(self) -> &'static str {
        match self {
            Species::Human => "h_sapiens",
            Species::Mouse => "m_musculus",
        }
    }

    /// Codon -> (amino acid, log usage frequency).
    fn codon_log_frequencies(self) -> &'static HashMap<&'static str, (char, f64)> {
        static HUMAN: OnceLock<HashMap<&'static str, (char, f64)>> = OnceLock::new();
        static MOUSE: OnceLock<HashMap<&'static str, (char, f64)>> = OnceLock::new();
        let (cell, source) = match self {
            Species::Human => (&HUMAN, &HUMAN_CODON_LOG_FREQ[..]),
            Species::Mouse => (&MOUSE, &MOUSE_CODON_LOG_FREQ[..]),
        };
        cell.get_or_init(|| {
            source
                .iter()
                .map(|(codon, amino_acid, log_frequency)| (*codon, (*amino_acid, *log_frequency)))
                .collect()
        })
    }

    /// Amino acid -> log frequency of its most-used codon.
    fn log_best(self) -> &'static HashMap<char, f64> {
        static HUMAN: OnceLock<HashMap<char, f64>> = OnceLock::new();
        static MOUSE: OnceLock<HashMap<char, f64>> = OnceLock::new();
        let (cell, source) = match self {
            Species::Human => (&HUMAN, &HUMAN_LOG_BEST[..]),
            Species::Mouse => (&MOUSE, &MOUSE_LOG_BEST[..]),
        };
        cell.get_or_init(|| source.iter().copied().collect())
    }
}

/// What `UniquifyAllKmers` remembers once it has been narrowed to a window:
/// which k-mer start positions can still change, and which k-mers are pinned
/// by the frozen remainder of the sequence.
#[derive(Debug, Clone)]
pub struct KmerLocalization {
    location_changing: Vec<usize>,
    location_fixed_kmers: HashSet<String>,
    extended_changing: Vec<usize>,
    extended_fixed_kmers: HashSet<String>,
}

/// The species a codon-usage table name refers to.
fn named(species: &str) -> Option<Species> {
    match species {
        "h_sapiens" => Some(Species::Human),
        "m_musculus" => Some(Species::Mouse),
        _ => None,
    }
}

/// Log usage frequency of a codon, for checking the generated tables.
pub(crate) fn log_frequency(species: &str, codon: &str) -> Option<f64> {
    named(species)?
        .codon_log_frequencies()
        .get(codon)
        .map(|(_, log_frequency)| *log_frequency)
}

/// Log usage frequency of an amino acid's most-used codon, which is what a
/// codon's preference is measured against.
pub(crate) fn log_best_frequency(species: &str, amino_acid: char) -> Option<f64> {
    named(species)?.log_best().get(&amino_acid).copied()
}

#[derive(Debug, Clone)]
pub enum Spec {
    /// Keep the protein identical. Satisfied by the mutation space.
    EnforceTranslation {
        location: Location,
        translation: String,
    },
    /// Freeze a span outright (used for an explicitly chosen WGGW site).
    AvoidChanges { location: Location, target: String },
    /// Penalise every occurrence of a pattern, on both strands.
    AvoidPattern {
        pattern: Pattern,
        location: Location,
        boost: f64,
    },
    /// Keep overall GC within bounds.
    EnforceGcContent {
        location: Location,
        mini: f64,
        maxi: f64,
        boost: f64,
    },
    /// Codon-optimize towards a species' most frequent codons (CAI).
    MaximizeCai {
        location: Location,
        species: Species,
        boost: f64,
    },
    /// Penalise repeated k-mers.
    UniquifyAllKmers {
        location: Location,
        reference: Location,
        k: usize,
        boost: f64,
        localization: Option<Box<KmerLocalization>>,
    },
}

#[derive(Debug, Clone)]
pub struct Evaluation {
    pub score: f64,
    pub locations: Vec<Location>,
    pub message: String,
}

impl Evaluation {
    pub fn passes(&self) -> bool {
        self.score >= 0.0
    }
}

/// Format a list of locations the way Python prints a list of them, since the
/// strings end up in the evaluation messages shown to users.
fn format_locations(locations: &[Location]) -> String {
    let inner: Vec<String> = locations.iter().map(|l| l.to_string()).collect();
    format!("[{}]", inner.join(", "))
}

/// DNAChisel's `score_to_formatted_string`: whichever of the plain, fixed and
/// scientific forms is shortest, right-justified to nine characters.
pub fn format_score(score: f64) -> String {
    let plain = if score == score.trunc() && score.is_finite() {
        format!("{}", score as i64)
    } else {
        // Python's str(float) gives the shortest round-tripping form, which is
        // also what Rust's {} does for f64.
        format!("{score}")
    };
    let fixed = format!("{score:.2}");
    let scientific = format_scientific(score);

    let shortest = [plain, fixed, scientific]
        .into_iter()
        .min_by_key(|candidate| candidate.len())
        .expect("three candidates");
    format!("{shortest:>9}")
}

/// Python's `"%.02E." % score` — note the trailing period, which is part of
/// the string DNAChisel compares lengths against.
fn format_scientific(score: f64) -> String {
    let formatted = format!("{score:.2E}");
    // Rust writes `1.2E5`; Python writes `1.20E+05`.
    let (mantissa, exponent) = formatted.split_once('E').unwrap_or((&formatted, "0"));
    let (sign, digits) = match exponent.strip_prefix('-') {
        Some(rest) => ('-', rest),
        None => ('+', exponent.trim_start_matches('+')),
    };
    format!("{mantissa}E{sign}{digits:0>2}.")
}

impl Spec {
    pub fn boost(&self) -> f64 {
        match self {
            Spec::EnforceTranslation { .. } | Spec::AvoidChanges { .. } => 1.0,
            Spec::AvoidPattern { boost, .. }
            | Spec::EnforceGcContent { boost, .. }
            | Spec::MaximizeCai { boost, .. }
            | Spec::UniquifyAllKmers { boost, .. } => *boost,
        }
    }

    /// Every spec used here is optimal at 0, which lets the solver stop early.
    pub fn best_possible_score(&self) -> f64 {
        0.0
    }

    /// True when satisfying the spec is guaranteed by the mutation space, so
    /// the solver can skip evaluating it entirely.
    pub fn enforced_by_nucleotide_restrictions(&self) -> bool {
        matches!(
            self,
            Spec::EnforceTranslation { .. } | Spec::AvoidChanges { .. }
        )
    }

    /// Constraints are resolved highest priority first.
    pub fn priority(&self) -> i32 {
        match self {
            Spec::AvoidPattern { .. } => 1,
            Spec::AvoidChanges { .. } => -1000,
            _ => 0,
        }
    }

    pub fn location(&self) -> Location {
        match self {
            Spec::EnforceTranslation { location, .. }
            | Spec::AvoidChanges { location, .. }
            | Spec::AvoidPattern { location, .. }
            | Spec::EnforceGcContent { location, .. }
            | Spec::MaximizeCai { location, .. }
            | Spec::UniquifyAllKmers { location, .. } => *location,
        }
    }

    /// The spec's name in reports, matching DNAChisel's `label()`.
    pub fn label(&self) -> String {
        let location = self.location();
        match self {
            // EnforceTranslation overrides __repr__ to use parentheses.
            Spec::EnforceTranslation { .. } => format!("EnforceTranslation({location})"),
            Spec::AvoidChanges { .. } => format!("AvoidChanges[{location}]"),
            Spec::AvoidPattern { pattern, .. } => {
                format!("AvoidPattern[{location}](pattern:{})", pattern.expression)
            }
            Spec::EnforceGcContent { mini, maxi, .. } => {
                format!("EnforceGCContent[{location}](mini:{mini:.2}, maxi:{maxi:.2})")
            }
            Spec::MaximizeCai { species, .. } => {
                format!("MaximizeCAI[{location}]({})", species.table_name())
            }
            Spec::UniquifyAllKmers { k, .. } => format!("UniquifyAllKmers[{location}](k:{k})"),
        }
    }

    pub fn evaluate(&self, sequence: &str) -> Evaluation {
        match self {
            Spec::EnforceTranslation {
                location,
                translation,
            } => evaluate_translation(sequence, location, translation),
            Spec::AvoidChanges { location, target } => {
                evaluate_avoid_changes(sequence, location, target)
            }
            Spec::AvoidPattern {
                pattern, location, ..
            } => evaluate_avoid_pattern(sequence, pattern, location),
            Spec::EnforceGcContent {
                location,
                mini,
                maxi,
                ..
            } => evaluate_gc_content(sequence, location, *mini, *maxi),
            Spec::MaximizeCai {
                location, species, ..
            } => evaluate_maximize_cai(sequence, location, *species),
            Spec::UniquifyAllKmers {
                location,
                reference,
                k,
                localization,
                ..
            } => match localization {
                Some(data) => evaluate_kmers_localized(sequence, *k, data),
                None => evaluate_kmers_global(sequence, location, reference, *k),
            },
        }
    }

    /// Narrow the spec to a window, or `None` when it no longer applies.
    ///
    /// `with_righthand = false` is DNAChisel's trick for overlapping breaches:
    /// only the left side is widened so neighbouring windows do not fight.
    pub fn localized(
        &self,
        window: &Location,
        sequence: &str,
        with_righthand: bool,
    ) -> Option<Spec> {
        let limit = sequence.len();
        match self {
            Spec::EnforceTranslation {
                location,
                translation,
            } => {
                let overlap = location.overlap(window)?;
                // Snap to codon boundaries and carry the matching slice of the
                // protein, as CodonSpecification.localized does.
                let start_codon = (overlap.start - location.start) / 3;
                let end_codon = (overlap.end - location.start - 1) / 3 + 1;
                let new_location = Location::with_strand(
                    location.start + 3 * start_codon,
                    location.end.min(location.start + 3 * end_codon),
                    location.strand,
                );
                Some(Spec::EnforceTranslation {
                    location: new_location,
                    translation: translation
                        [start_codon.min(translation.len())..end_codon.min(translation.len())]
                        .to_string(),
                })
            }
            Spec::AvoidChanges { location, target } => {
                let overlap = location.overlap(window)?;
                let relative = overlap.start - location.start..overlap.end - location.start;
                Some(Spec::AvoidChanges {
                    location: overlap,
                    target: target[relative].to_string(),
                })
            }
            Spec::AvoidPattern {
                pattern,
                location,
                boost,
            } => {
                location.overlap(window)?;
                let extended = window.extended(pattern.size() - 1, limit, with_righthand);
                let new_location = location.overlap(&extended)?;
                Some(Spec::AvoidPattern {
                    pattern: pattern.clone(),
                    location: new_location,
                    boost: *boost,
                })
            }
            // Without a sliding window there is no cheaper local form of GC
            // content, so DNAChisel keeps the global spec. Dropping it here
            // would let local searches breach GC bounds.
            Spec::EnforceGcContent { .. } => Some(self.clone()),
            Spec::MaximizeCai {
                location,
                species,
                boost,
            } => {
                let overlap = location.overlap(window)?;
                let start_codon = (overlap.start - location.start) / 3;
                let end_codon = (overlap.end - location.start - 1) / 3 + 1;
                Some(Spec::MaximizeCai {
                    location: Location::with_strand(
                        location.start + 3 * start_codon,
                        location.end.min(location.start + 3 * end_codon),
                        location.strand,
                    ),
                    species: *species,
                    boost: *boost,
                })
            }
            Spec::UniquifyAllKmers {
                location,
                reference,
                k,
                boost,
                ..
            } => {
                reference.overlap(window)?;
                let k = *k;
                let extended = window.extended(k - 1, limit, with_righthand);
                let changing_zone = extended.overlap(reference)?;

                // Start positions whose k-mer can still change. DNAChisel drops
                // the last k-1 indices of the zone here...
                let changing: HashSet<usize> =
                    starts_dropping_last(&changing_zone, k.saturating_sub(1))
                        .into_iter()
                        .collect();

                // ...but the last k when listing a spec's own k-mer starts. The
                // mismatch is DNAChisel's, and it shifts which k-mers count as
                // fixed, so it is reproduced rather than corrected.
                let build = |span: &Location| {
                    let indices: Vec<usize> = starts_dropping_last(span, k);
                    let (changing_indices, fixed_indices): (Vec<usize>, Vec<usize>) =
                        indices.into_iter().partition(|i| changing.contains(i));
                    let fixed_kmers = fixed_indices
                        .iter()
                        .map(|&i| extract_kmer(sequence, i, k))
                        .collect::<HashSet<String>>();
                    (changing_indices, fixed_kmers)
                };

                let (location_changing, location_fixed_kmers) = build(location);
                let (extended_changing, extended_fixed_kmers) = build(reference);
                // The extended set keeps only what the location set does not
                // already cover; with location == reference it empties out.
                let location_set: HashSet<usize> = location_changing.iter().copied().collect();
                let extended_changing: Vec<usize> = extended_changing
                    .into_iter()
                    .filter(|i| !location_set.contains(i))
                    .collect();

                Some(Spec::UniquifyAllKmers {
                    location: changing_zone,
                    reference: *reference,
                    k,
                    boost: *boost,
                    localization: Some(Box::new(KmerLocalization {
                        location_changing,
                        location_fixed_kmers,
                        extended_changing,
                        extended_fixed_kmers,
                    })),
                })
            }
        }
    }

    /// Segments the spec pins, as `(span, allowed variants)`.
    ///
    /// This is how a constraint shapes the mutation space: EnforceTranslation
    /// offers each codon's synonyms, AvoidChanges offers only what is already
    /// there. Everything else leaves the space alone.
    pub fn restrict_nucleotides(&self, sequence: &str) -> Vec<((usize, usize), Vec<String>)> {
        match self {
            Spec::EnforceTranslation {
                location,
                translation,
            } => {
                let table = backtranslation();
                translation
                    .chars()
                    .enumerate()
                    .map(|(index, amino_acid)| {
                        let start = location.start + 3 * index;
                        let codons = table
                            .get(&amino_acid)
                            .map(|codons| codons.iter().map(|c| c.to_string()).collect())
                            .unwrap_or_else(|| vec![sequence[start..start + 3].to_string()]);
                        ((start, start + 3), codons)
                    })
                    .collect()
            }
            Spec::AvoidChanges { location, .. } => vec![(
                (location.start, location.end),
                vec![location.extract(sequence).to_string()],
            )],
            _ => Vec::new(),
        }
    }
}

/// Indices of a span with its last `drop` positions removed.
///
/// DNAChisel uses two different values of `drop` when localizing k-mers (see
/// the call sites); isolating it here keeps that asymmetry visible.
fn starts_dropping_last(span: &Location, drop: usize) -> Vec<usize> {
    (span.start..span.end.saturating_sub(drop)).collect()
}

/// The canonical form of the k-mer at `index`: whichever of it and its reverse
/// complement sorts first, so a repeat is found on either strand.
fn extract_kmer(sequence: &str, index: usize, k: usize) -> String {
    let end = (index + k).min(sequence.len());
    let forward = &sequence[index.min(sequence.len())..end];
    let reverse = reverse_complement(forward);
    if forward <= reverse.as_str() {
        forward.to_string()
    } else {
        reverse
    }
}

fn evaluate_translation(sequence: &str, location: &Location, expected: &str) -> Evaluation {
    let observed = translate(location.extract(sequence));
    let errors: Vec<Location> = observed
        .chars()
        .zip(expected.chars())
        .enumerate()
        .filter(|(_, (got, want))| got != want)
        .map(|(index, _)| {
            Location::with_strand(
                location.start + 3 * index,
                location.start + 3 * (index + 1),
                1,
            )
        })
        .collect();

    let message = if errors.is_empty() {
        "All OK.".to_string()
    } else {
        format!(
            "Wrong translation at locations {}",
            format_locations(&errors)
        )
    };
    Evaluation {
        score: -(errors.len() as f64),
        locations: errors,
        message,
    }
}

fn evaluate_avoid_changes(sequence: &str, location: &Location, target: &str) -> Evaluation {
    let differing = differing_indices(location.extract(sequence), target);
    let absolute: Vec<usize> = differing.iter().map(|i| i + location.start).collect();
    // Changed positions within six bases of each other report as one span.
    let locations: Vec<Location> = group_nearby_indices(&absolute, 6)
        .into_iter()
        .map(|group| Location::with_strand(group[0], group[group.len() - 1] + 1, 1))
        .collect();
    let score = -(differing.len() as f64);
    Evaluation {
        message: format!(
            "Score: {}. Locations: {}",
            format_score(score),
            format_locations(&locations)
        ),
        score,
        locations,
    }
}

fn evaluate_avoid_pattern(sequence: &str, pattern: &Pattern, location: &Location) -> Evaluation {
    let locations: Vec<Location> = pattern
        .find_matches(sequence, location.start, location.end, location.strand)
        .into_iter()
        .map(|(start, end, strand)| Location::with_strand(start, end, strand))
        .collect();

    let message = if locations.is_empty() {
        "Passed. Pattern not found !".to_string()
    } else {
        format!(
            "Failed. Pattern found at positions {}",
            format_locations(&locations)
        )
    };
    Evaluation {
        score: -(locations.len() as f64),
        locations,
        message,
    }
}

fn evaluate_gc_content(sequence: &str, location: &Location, mini: f64, maxi: f64) -> Evaluation {
    let gc = gc_content(location.extract(sequence));
    let breach = (mini - gc).max(0.0) + (gc - maxi).max(0.0);

    if breach <= 0.0 {
        return Evaluation {
            score: 0.0,
            locations: Vec::new(),
            message: "Passed !".to_string(),
        };
    }
    // Without a sliding window the whole span is the single breach.
    let locations = vec![Location::new(location.start, location.end)];
    Evaluation {
        score: -breach,
        message: format!(
            "Out of bound on segments {}",
            locations
                .iter()
                .map(|l| l.to_string())
                .collect::<Vec<_>>()
                .join(", ")
        ),
        locations,
    }
}

fn evaluate_maximize_cai(sequence: &str, location: &Location, species: Species) -> Evaluation {
    let subsequence = location.extract(sequence);
    let frequencies = species.codon_log_frequencies();
    let best = species.log_best();

    let codons: Vec<&str> = subsequence
        .as_bytes()
        .as_chunks::<3>()
        .0
        .iter()
        .map(|codon| std::str::from_utf8(codon).unwrap_or("NNN"))
        .collect();

    // How far each codon falls short of the best synonymous codon.
    let shortfalls: Vec<f64> = codons
        .iter()
        .map(|codon| match frequencies.get(codon) {
            Some((amino_acid, log_frequency)) => {
                best.get(amino_acid).copied().unwrap_or(0.0) - log_frequency
            }
            None => 0.0,
        })
        .collect();

    let score = -shortfalls.iter().sum::<f64>();

    // A single codon reports the whole (one-codon) window, not a sub-span.
    if codons.len() == 1 {
        let locations = if shortfalls[0] == 0.0 {
            Vec::new()
        } else {
            vec![*location]
        };
        return Evaluation {
            score,
            locations,
            message: format!(
                "Codon opt. on window {location} scored {}",
                format_scientific_bare(score)
            ),
        };
    }

    let suboptimal: Vec<usize> = shortfalls
        .iter()
        .enumerate()
        .filter(|(_, shortfall)| **shortfall != 0.0)
        .map(|(index, _)| location.start + 3 * index)
        .collect();
    // Codon starts are three apart and the grouping spread is three, so every
    // suboptimal codon becomes its own location.
    let locations: Vec<Location> = group_nearby_indices(&suboptimal, 3)
        .into_iter()
        .map(|group| Location::new(group[0], group[group.len() - 1] + 3))
        .collect();

    Evaluation {
        score,
        locations,
        message: format!(
            "Codon opt. on window {location} scored {}",
            format_scientific_bare(score)
        ),
    }
}

/// Python's `"%.02E"` (no trailing period), used inside CAI messages.
fn format_scientific_bare(value: f64) -> String {
    let formatted = format!("{value:.2E}");
    let (mantissa, exponent) = formatted.split_once('E').unwrap_or((&formatted, "0"));
    let (sign, digits) = match exponent.strip_prefix('-') {
        Some(rest) => ('-', rest),
        None => ('+', exponent.trim_start_matches('+')),
    };
    format!("{mantissa}E{sign}{digits:0>2}")
}

fn evaluate_kmers_global(
    sequence: &str,
    location: &Location,
    reference: &Location,
    k: usize,
) -> Evaluation {
    let mut positions_by_kmer: HashMap<String, Vec<usize>> = HashMap::new();
    let mut order: Vec<String> = Vec::new();
    for index in reference.start..=reference.end.saturating_sub(k) {
        let kmer = extract_kmer(sequence, index, k);
        positions_by_kmer
            .entry(kmer.clone())
            .or_insert_with(|| {
                order.push(kmer.clone());
                Vec::new()
            })
            .push(index);
    }

    let mut locations: Vec<Location> = positions_by_kmer
        .values()
        .filter(|positions| positions.len() > 1)
        .flat_map(|positions| positions.iter().copied())
        .filter(|start| location.start <= *start && start + k <= location.end)
        .map(|start| Location::new(start, start + k))
        .collect();
    locations.sort_by_key(|l| l.start);

    if locations.is_empty() {
        return Evaluation {
            score: 0.0,
            locations,
            message: format!("Passed: no nonunique {k}-mer found."),
        };
    }
    Evaluation {
        score: -(locations.len() as f64),
        message: format!(
            "Failed, the following positions are the first occurences of non-unique segments {}",
            format_locations(&locations)
        ),
        locations,
    }
}

fn evaluate_kmers_localized(sequence: &str, k: usize, data: &KmerLocalization) -> Evaluation {
    let collect = |indices: &[usize]| {
        let mut by_kmer: HashMap<String, Vec<usize>> = HashMap::new();
        for &index in indices {
            by_kmer
                .entry(extract_kmer(sequence, index, k))
                .or_default()
                .push(index);
        }
        by_kmer
    };
    let location_kmers = collect(&data.location_changing);
    let extended_kmers = collect(&data.extended_changing);

    let mut nonunique: Vec<usize> = Vec::new();
    // A changeable k-mer that repeats among the changeable positions.
    for positions in location_kmers.values() {
        if positions.len() > 1 {
            nonunique.extend(positions.iter().copied());
        }
    }

    // Then collisions with the other three sets. DNAChisel checks the fixed
    // k-mers of the location and of the reference separately; when the two
    // spans are the same (as they are here) that counts those collisions
    // twice. Matching the Python score means keeping the double count.
    let location_kmer_set: HashSet<&String> = location_kmers.keys().collect();
    let extended_kmer_set: HashSet<&String> = extended_kmers.keys().collect();
    for other in [
        &extended_kmer_set,
        &data.location_fixed_kmers.iter().collect(),
        &data.extended_fixed_kmers.iter().collect(),
    ] {
        for kmer in location_kmer_set.intersection(other) {
            nonunique.extend(location_kmers[*kmer].iter().copied());
        }
    }
    for other in [
        &location_kmer_set,
        &data
            .location_fixed_kmers
            .iter()
            .collect::<HashSet<&String>>(),
    ] {
        for kmer in extended_kmer_set.intersection(other) {
            nonunique.extend(extended_kmers[*kmer].iter().copied());
        }
    }

    let locations: Vec<Location> = nonunique
        .into_iter()
        .map(|index| Location::new(index, index + k))
        .collect();
    Evaluation {
        score: -(locations.len() as f64),
        message: format!(
            "Failed, the following positions are the first occurencesof local non-unique segments {}",
            format_locations(&locations)
        ),
        locations,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const CDS: &str =
        "ATGCGTAAGCTGGACTCCGAAGACGATCTGGAACGTCTGAAAGCGACCCTGGAAGGCGTTGACTCCGTGATCACCGATTGA";

    fn whole(sequence: &str) -> Location {
        Location::with_strand(0, sequence.len(), 1)
    }

    #[test]
    fn translation_passes_on_an_unchanged_sequence() {
        let spec = Spec::EnforceTranslation {
            location: whole(CDS),
            translation: translate(CDS),
        };
        let evaluation = spec.evaluate(CDS);
        assert_eq!(evaluation.score, 0.0);
        assert_eq!(evaluation.message, "All OK.");
        assert!(evaluation.passes());
    }

    #[test]
    fn translation_reports_each_broken_codon() {
        let spec = Spec::EnforceTranslation {
            location: whole(CDS),
            translation: translate(CDS),
        };
        // Change codon 1 (CGT, Arg) to CCT (Pro).
        let mutated = format!("{}CCT{}", &CDS[..3], &CDS[6..]);
        let evaluation = spec.evaluate(&mutated);
        assert_eq!(evaluation.score, -1.0);
        assert_eq!(evaluation.locations, vec![Location::with_strand(3, 6, 1)]);
        assert!(!evaluation.passes());
    }

    #[test]
    fn translation_offers_synonymous_codons_to_the_mutation_space() {
        let spec = Spec::EnforceTranslation {
            location: whole(CDS),
            translation: translate(CDS),
        };
        let restrictions = spec.restrict_nucleotides(CDS);
        assert_eq!(restrictions.len(), CDS.len() / 3);
        // Methionine has exactly one codon; arginine has six.
        assert_eq!(restrictions[0], ((0, 3), vec!["ATG".to_string()]));
        assert_eq!(restrictions[1].1.len(), 6);
    }

    #[test]
    fn avoid_pattern_counts_one_hit_per_occurrence() {
        // The design builds these on the + strand, so each CpG counts once.
        let spec = Spec::AvoidPattern {
            pattern: Pattern::parse("CG").unwrap(),
            location: Location::with_strand(0, 12, 1),
            boost: 1.0,
        };
        let evaluation = spec.evaluate("ACGTACGTACGT");
        assert_eq!(evaluation.score, -3.0);
        assert_eq!(
            evaluation.locations,
            vec![
                Location::with_strand(1, 3, 1),
                Location::with_strand(5, 7, 1),
                Location::with_strand(9, 11, 1),
            ]
        );
    }

    #[test]
    fn gc_content_scores_the_size_of_the_breach() {
        let spec = Spec::EnforceGcContent {
            location: Location::with_strand(0, 4, 1),
            mini: 0.35,
            maxi: 0.60,
            boost: 1.0,
        };
        assert_eq!(spec.evaluate("ATGC").score, 0.0);
        // All GC: 1.0 is 0.4 above the 0.6 ceiling.
        let breach = spec.evaluate("GCGC");
        assert!((breach.score - -0.4).abs() < 1e-12);
        assert_eq!(breach.locations, vec![Location::new(0, 4)]);
    }

    #[test]
    fn cai_is_zero_when_every_codon_is_already_the_best() {
        // ATG and TGA are the only codons for M and the chosen stop here, but
        // CTG/GAG are also the most frequent for L/E in humans.
        let spec = Spec::MaximizeCai {
            location: Location::with_strand(0, 9, 1),
            species: Species::Human,
            boost: 1.0,
        };
        let evaluation = spec.evaluate("ATGCTGGAG");
        assert!(
            evaluation.score.abs() < 1e-12,
            "score was {}",
            evaluation.score
        );
        assert!(evaluation.locations.is_empty());
    }

    #[test]
    fn cai_penalises_and_locates_rare_codons() {
        let spec = Spec::MaximizeCai {
            location: Location::with_strand(0, 9, 1),
            species: Species::Human,
            boost: 1.0,
        };
        // CTA is a rare leucine codon, so codon 1 is suboptimal.
        let evaluation = spec.evaluate("ATGCTAGAG");
        assert!(evaluation.score < 0.0);
        assert_eq!(evaluation.locations, vec![Location::new(3, 6)]);
    }

    #[test]
    fn kmers_find_a_planted_repeat() {
        let sequence = "AAAACCCCGGGGTTTTAAAACCCC";
        let spec = Spec::UniquifyAllKmers {
            location: whole(sequence),
            reference: whole(sequence),
            k: 8,
            boost: 1.0,
            localization: None,
        };
        let evaluation = spec.evaluate(sequence);
        assert!(evaluation.score < 0.0);
        assert!(!evaluation.passes());
    }

    #[test]
    fn kmers_pass_on_a_sequence_without_repeats() {
        let spec = Spec::UniquifyAllKmers {
            location: whole(CDS),
            reference: whole(CDS),
            k: 10,
            boost: 1.0,
            localization: None,
        };
        let evaluation = spec.evaluate(CDS);
        assert_eq!(evaluation.score, 0.0);
        assert_eq!(evaluation.message, "Passed: no nonunique 10-mer found.");
    }

    #[test]
    fn labels_match_dnachisel() {
        let spec = Spec::AvoidPattern {
            pattern: Pattern::parse("GT[AG]A").unwrap(),
            location: Location::with_strand(0, 81, 1),
            boost: 1.0,
        };
        assert_eq!(spec.label(), "AvoidPattern[0-81(+)](pattern:GT[AG]A)");

        let spec = Spec::EnforceGcContent {
            location: Location::with_strand(0, 81, 1),
            mini: 0.35,
            maxi: 0.60,
            boost: 1.0,
        };
        assert_eq!(
            spec.label(),
            "EnforceGCContent[0-81(+)](mini:0.35, maxi:0.60)"
        );

        let spec = Spec::MaximizeCai {
            location: Location::with_strand(0, 81, 1),
            species: Species::Human,
            boost: 1.0,
        };
        assert_eq!(spec.label(), "MaximizeCAI[0-81(+)](h_sapiens)");

        let spec = Spec::UniquifyAllKmers {
            location: Location::with_strand(0, 81, 1),
            reference: Location::with_strand(0, 81, 1),
            k: 10,
            boost: 1.0,
            localization: None,
        };
        assert_eq!(spec.label(), "UniquifyAllKmers[0-81(+)](k:10)");
    }

    #[test]
    fn score_formatting_matches_python() {
        assert_eq!(format_score(0.0), "        0");
        assert_eq!(format_score(-2.0), "       -2");
        // "-12.5" is shorter than "-12.50", so the plain form wins.
        assert_eq!(format_score(-12.5), "    -12.5");
    }
}
